private static int decodeOctets(byte[] octets, int index, int limit, StringBuilder builder) {
    while (index < limit) {
        int b1 = octets[index] & 0xFF;

        if (b1 < 0x80) {
            builder.append((char) b1);
            index++;
            continue;
        }

        int length;
        int codePoint;

        if (b1 >= 0xC2 && b1 <= 0xDF) {
            length = 2;
            codePoint = b1 & 0x1F;
        } else if (b1 >= 0xE0 && b1 <= 0xEF) {
            length = 3;
            codePoint = b1 & 0x0F;
        } else if (b1 >= 0xF0 && b1 <= 0xF4) {
            length = 4;
            codePoint = b1 & 0x07;
        } else {
            return index;
        }

        if (index + length > limit) {
            return index;
        }

        int b2 = octets[index + 1] & 0xFF;
        if ((b2 & 0xC0) != 0x80
                || (length == 3 && b1 == 0xE0 && b2 < 0xA0)
                || (length == 3 && b1 == 0xED && b2 >= 0xA0)
                || (length == 4 && b1 == 0xF0 && b2 < 0x90)
                || (length == 4 && b1 == 0xF4 && b2 >= 0x90)) {
            return index;
        }

        for (int i = 1; i < length; i++) {
            int continuation = octets[index + i] & 0xFF;
            if ((continuation & 0xC0) != 0x80) {
                return index;
            }
            codePoint = (codePoint << 6) | (continuation & 0x3F);
        }

        builder.appendCodePoint(codePoint);
        index += length;
    }

    return index;
}

