        Map<String, ?> current,
        Map<String, ?> history) {

    Objects.requireNonNull(current, "current");
    Objects.requireNonNull(history, "history");

    Map<String, Object> missing = new LinkedHashMap<>();

    for (Map.Entry<String, ?> entry : current.entrySet()) {
        String key = entry.getKey();
        Object currentValue = entry.getValue();

        if (!history.containsKey(key)) {
            missing.put(key, currentValue);
            continue;
        }

        Object historyValue = history.get(key);
        if (currentValue instanceof Map<?, ?> currentMap
                && historyValue instanceof Map<?, ?> historyMap) {
            Map<Object, Object> nestedMissing = new LinkedHashMap<>();

            for (Map.Entry<?, ?> nestedEntry : currentMap.entrySet()) {
                Object nestedKey = nestedEntry.getKey();

                if (!historyMap.containsKey(nestedKey)) {
                    nestedMissing.put(nestedKey, nestedEntry.getValue());
                } else if (nestedEntry.getValue() instanceof Map<?, ?>
                        && historyMap.get(nestedKey) instanceof Map<?, ?>) {
                    @SuppressWarnings("unchecked")
                    Map<String, ?> nestedCurrent =
                            (Map<String, ?>) nestedEntry.getValue();
                    @SuppressWarnings("unchecked")
                    Map<String, ?> nestedHistory =
                            (Map<String, ?>) historyMap.get(nestedKey);

                    Map<String, Object> deeper =
                            diffStructure(nestedCurrent, nestedHistory);
                    if (!deeper.isEmpty()) {
                        nestedMissing.put(nestedKey, deeper);
                    }
                }
            }

            if (!nestedMissing.isEmpty()) {
                missing.put(key, nestedMissing);
            }
        }
    }

    return missing;
}

