    String osName = System.getProperty("os.name", "").toLowerCase(java.util.Locale.ROOT);
    java.io.File directory;

    if (osName.startsWith("windows")) {
        String systemDrive = System.getenv("SystemDrive");
        if (systemDrive == null || systemDrive.trim().isEmpty()) {
            systemDrive = "C:";
        }
        directory = new java.io.File(systemDrive + java.io.File.separator
                + "Documents and Settings", "lf5");
    } else {
        directory = new java.io.File(System.getProperty("user.home"), "lf5");
    }

    if (!directory.isDirectory() && !directory.mkdirs() && !directory.isDirectory()) {
        throw new IllegalStateException(
                "Unable to create configuration directory: " + directory.getAbsolutePath());
    }
}

