public static File createConfigurationDirectory() throws IOException {
    String osName = System.getProperty("os.name", "");
    String userHome = System.getProperty("user.home");

    if (userHome == null || userHome.trim().isEmpty()) {
        throw new IOException("The user.home system property is not defined.");
    }

    File baseDirectory = new File(userHome);

    if (osName.toLowerCase(java.util.Locale.ROOT).startsWith("windows")) {
        File documentsAndSettings = new File("C:\\Documents and Settings");
        if (documentsAndSettings.isDirectory()) {
            baseDirectory = documentsAndSettings;
        }
    }

    File configurationDirectory = new File(baseDirectory, "lf5");

    if (!configurationDirectory.isDirectory()
            && !configurationDirectory.mkdirs()
            && !configurationDirectory.isDirectory()) {
        throw new IOException(
                "Unable to create configuration directory: "
                        + configurationDirectory.getAbsolutePath());
    }

    return configurationDirectory;
}

