public long readLong() {
    int c;
    do {
        c = read();
    } while (c <= ' ' && c != -1);

    boolean negative = c == '-';
    if (negative) {
        c = read();
    }

    long limit = negative ? Long.MIN_VALUE : -Long.MAX_VALUE;
    long multMin = limit / 10;
    long result = 0;

    while (c >= '0' && c <= '9') {
        int digit = c - '0';
        if (result < multMin) {
            throw new NumberFormatException("Long overflow");
        }
        result *= 10;
        if (result < limit + digit) {
            throw new NumberFormatException("Long overflow");
        }
        result -= digit;
        c = read();
    }

    return negative ? result : -result;
}

