public static long readLong() throws java.io.IOException {
    java.io.BufferedInputStream in = new java.io.BufferedInputStream(System.in);
    int c;

    do {
        c = in.read();
    } while (c <= ' ' && c != -1);

    if (c == -1) {
        throw new java.io.EOFException("No long value found");
    }

    boolean negative = false;
    if (c == '-' || c == '+') {
        negative = c == '-';
        c = in.read();
    }

    if (c < '0' || c > '9') {
        throw new NumberFormatException("Invalid long value");
    }

    long limit = negative ? Long.MIN_VALUE : -Long.MAX_VALUE;
    long result = 0;
    long multiplyLimit = limit / 10;

    do {
        int digit = c - '0';

        if (result < multiplyLimit) {
            throw new NumberFormatException("Long value out of range");
        }

        result *= 10;

        if (result < limit + digit) {
            throw new NumberFormatException("Long value out of range");
        }

        result -= digit;
        c = in.read();
    } while (c >= '0' && c <= '9');

    if (c != -1 && c > ' ') {
        throw new NumberFormatException("Invalid character after long value");
    }

    return negative ? result : -result;
}

