                           .replace('\r', '\n')
                           .replace("\n", "\r\n")
                           .getBytes(StandardCharsets.US_ASCII);

    for (Connection connection : connections) {
        connection.getOutputStream().write(output);
        connection.getOutputStream().flush();
    }
}

