        Instant startTime,
        Instant endTime,
        Duration fetchDataDuration) {

    if (startTime == null || endTime == null || fetchDataDuration == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }
    if (fetchDataDuration.isZero() || fetchDataDuration.isNegative()) {
        throw new IllegalArgumentException("fetchDataDuration must be positive");
    }
    if (startTime.isAfter(endTime)) {
        throw new IllegalArgumentException("startTime must not be after endTime");
    }

    List<TimeRange> ranges = new ArrayList<>();
    Instant rangeStart = startTime;

    while (rangeStart.isBefore(endTime)) {
        Instant rangeEnd;
        try {
            rangeEnd = rangeStart.plus(fetchDataDuration);
        } catch (DateTimeException | ArithmeticException e) {
            rangeEnd = endTime;
        }

        if (rangeEnd.isAfter(endTime)) {
            rangeEnd = endTime;
        }

        ranges.add(new TimeRange(rangeStart, rangeEnd));
        rangeStart = rangeEnd;
    }

    return ranges;
}

