public void writeUTF8(String value, LinkedBuffer buffer) {
    if (value == null) {
        throw new NullPointerException("value");
    }

    LinkedBuffer current = buffer;
    byte[] bytes = current.buffer;
    int offset = current.offset;

    for (int i = 0, length = value.length(); i < length; i++) {
        int c = value.charAt(i);

        if (c < 0x80) {
            if (offset == bytes.length) {
                current.offset = offset;
                current = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE, current);
                bytes = current.buffer;
                offset = current.offset;
            }
            bytes[offset++] = (byte) c;
        } else {
            int codePoint;
            if (c < 0x800) {
                codePoint = c;
            } else if (Character.isHighSurrogate((char) c)
                    && i + 1 < length
                    && Character.isLowSurrogate(value.charAt(i + 1))) {
                codePoint = Character.toCodePoint((char) c, value.charAt(++i));
            } else if (Character.isSurrogate((char) c)) {
                codePoint = 0xFFFD;
            } else {
                codePoint = c;
            }

            int count = codePoint < 0x800 ? 2 : codePoint < 0x10000 ? 3 : 4;
            for (int shift = (count - 1) * 6; shift >= 0; shift -= 6) {
                if (offset == bytes.length) {
                    current.offset = offset;
                    current = LinkedBuffer.allocate(LinkedBuffer.DEFAULT_BUFFER_SIZE, current);
                    bytes = current.buffer;
                    offset = current.offset;
                }

                bytes[offset++] = shift == (count - 1) * 6
                        ? (byte) ((0xF0 << (4 - count)) | (codePoint >>> shift))
                        : (byte) (0x80 | ((codePoint >>> shift) & 0x3F));
            }
        }
    }

    current.offset = offset;
}

