public static LinkedBuffer writeUTF8(final CharSequence str,
                                     final WriteSession session,
                                     final LinkedBuffer lb) {
    LinkedBuffer buffer = lb;
    byte[] data = buffer.buffer;
    int offset = buffer.offset;

    for (int i = 0, length = str.length(); i < length; i++) {
        final char c = str.charAt(i);
        int required;

        if (c < 0x80) {
            required = 1;
        } else if (c < 0x800) {
            required = 2;
        } else if (Character.isHighSurrogate(c)
                && i + 1 < length
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            required = 4;
        } else {
            required = 3;
        }

        if (offset + required > data.length) {
            buffer.offset = offset;
            buffer = new LinkedBuffer(Math.max(session.nextBufferSize, required), buffer);
            data = buffer.buffer;
            offset = buffer.offset;
        }

        if (required == 1) {
            data[offset++] = (byte) c;
        } else if (required == 2) {
            data[offset++] = (byte) (0xC0 | (c >>> 6));
            data[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (required == 4) {
            final int codePoint = Character.toCodePoint(c, str.charAt(++i));
            data[offset++] = (byte) (0xF0 | (codePoint >>> 18));
            data[offset++] = (byte) (0x80 | ((codePoint >>> 12) & 0x3F));
            data[offset++] = (byte) (0x80 | ((codePoint >>> 6) & 0x3F));
            data[offset++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            data[offset++] = (byte) (0xE0 | (c >>> 12));
            data[offset++] = (byte) (0x80 | ((c >>> 6) & 0x3F));
            data[offset++] = (byte) (0x80 | (c & 0x3F));
        }

        session.size += required;
    }

    buffer.offset = offset;
    return buffer;
}

