    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    try {
        StringBuilder result = new StringBuilder();
        int index = 0;

        while (index < value.length()) {
            int start = value.indexOf("${", index);
            if (start < 0) {
                result.append(value, index, value.length());
                break;
            }

            result.append(value, index, start);
            int end = value.indexOf('}', start + 2);
            if (end < 0) {
                throw new IllegalArgumentException("Unclosed variable");
            }

            String variable = value.substring(start + 2, end);
            String replacement = props.getProperty(variable);
            if (replacement == null) {
                replacement = System.getProperty(variable);
            }
            if (replacement == null) {
                throw new IllegalArgumentException("Undefined variable: " + variable);
            }

            result.append(replacement);
            index = end + 1;
        }

        return result.toString();
    } catch (Exception e) {
        return value;
    }
}

