public static String decodePath(String rawPath) {
    if (rawPath == null) {
        return null;
    }

    StringBuilder decoded = new StringBuilder(rawPath.length());
    java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();

    for (int i = 0; i < rawPath.length(); ) {
        if (rawPath.charAt(i) != '%') {
            decoded.append(rawPath.charAt(i++));
            continue;
        }

        bytes.reset();
        while (i + 2 < rawPath.length() && rawPath.charAt(i) == '%') {
            int high = Character.digit(rawPath.charAt(i + 1), 16);
            int low = Character.digit(rawPath.charAt(i + 2), 16);
            if (high < 0 || low < 0) {
                break;
            }
            bytes.write((high << 4) | low);
            i += 3;
        }

        if (bytes.size() == 0) {
            throw new IllegalArgumentException("Invalid percent-encoding at index " + i);
        }

        decoded.append(new String(bytes.toByteArray(), java.nio.charset.StandardCharsets.UTF_8));
    }

    return decoded.toString();
}

