public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String rawPath = u.getRawPath();
    List<PathSegmentImpl> segments = new ArrayList<PathSegmentImpl>();

    if (rawPath == null || rawPath.length() == 0) {
        return segments;
    }

    int start = rawPath.charAt(0) == '/' ? 1 : 0;
    int end;

    while (start <= rawPath.length()) {
        end = rawPath.indexOf('/', start);
        if (end == -1) {
            end = rawPath.length();
        }

        segments.add(new PathSegmentImpl(rawPath.substring(start, end), decode));

        if (end == rawPath.length()) {
            break;
        }
        start = end + 1;
    }

    return segments;
}

