public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getRawPath();
    if (path == null || path.isEmpty() || "/".equals(path)) {
        return java.util.Collections.emptyList();
    }

    int start = path.charAt(0) == '/' ? 1 : 0;
    int segmentCount = 1;
    for (int i = start; i < path.length(); i++) {
        if (path.charAt(i) == '/') {
            segmentCount++;
        }
    }

    List<PathSegmentImpl> segments = new java.util.ArrayList<>(segmentCount);
    int end;
    do {
        end = path.indexOf('/', start);
        if (end < 0) {
            end = path.length();
        }

        String segment = path.substring(start, end);
        int matrixStart = segment.indexOf(';');
        String rawName = matrixStart < 0 ? segment : segment.substring(0, matrixStart);
        String name = decode ? java.net.URLDecoder.decode(
                rawName.replace("+", "%2B"),
                java.nio.charset.StandardCharsets.UTF_8) : rawName;

        javax.ws.rs.core.MultivaluedMap<String, String> matrix =
                new javax.ws.rs.core.MultivaluedHashMap<>();

        while (matrixStart >= 0) {
            int next = segment.indexOf(';', matrixStart + 1);
            String parameter = segment.substring(
                    matrixStart + 1, next < 0 ? segment.length() : next);
            int equals = parameter.indexOf('=');

            String rawKey = equals < 0 ? parameter : parameter.substring(0, equals);
            String rawValue = equals < 0 ? "" : parameter.substring(equals + 1);

            String key = decode ? java.net.URLDecoder.decode(
                    rawKey.replace("+", "%2B"),
                    java.nio.charset.StandardCharsets.UTF_8) : rawKey;
            String value = decode ? java.net.URLDecoder.decode(
                    rawValue.replace("+", "%2B"),
                    java.nio.charset.StandardCharsets.UTF_8) : rawValue;

            matrix.add(key, value);
            matrixStart = next;
        }

        segments.add(new PathSegmentImpl(name, matrix));
        start = end + 1;
    } while (end < path.length());

    return segments;
}

