public void writeTo(final LinkedBuffer buffer) throws IOException {
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }

    LinkedBuffer current = buffer;
    int offset = current.offset;

    for (int i = 0; i < length; i++) {
        if (offset == current.buffer.length) {
            if (current.next == null) {
                current.next = new LinkedBuffer(current.buffer.length);
            }
            current = current.next;
            offset = current.offset;
        }

        current.buffer[offset++] = content[i];
        current.offset = offset;
    }
}

