public static java.util.function.Supplier<String> createStringSupplier(int start) {
    java.util.concurrent.atomic.AtomicInteger next =
            new java.util.concurrent.atomic.AtomicInteger(start);

    return () -> {
        int value = next.getAndUpdate(current -> {
            if (current == Integer.MAX_VALUE) {
                throw new IllegalStateException("No more unique integer strings available");
            }
            return current + 1;
        });
        return Integer.toString(value);
