public static int nextPrime(int desiredCapacity) {
    int low = 0;
    int high = primeCapacities.length - 1;

    while (low < high) {
        int mid = low + (high - low) / 2;
        if (primeCapacities[mid] < desiredCapacity) {
            low = mid + 1;
        } else {
            high = mid;
