public static String unescapeJava(String input) {
    if (input == null) {
        return null;
    }

    StringBuilder result = new StringBuilder(input.length());

    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);

        if (c != '\\') {
            result.append(c);
            continue;
        }

        if (++i >= input.length()) {
            result.append('\\');
            break;
        }

        c = input.charAt(i);
        switch (c) {
            case 'b':
                result.append('\b');
                break;
            case 't':
                result.append('\t');
                break;
            case 'n':
                result.append('\n');
                break;
            case 'f':
                result.append('\f');
                break;
            case 'r':
                result.append('\r');
                break;
            case '"':
                result.append('"');
                break;
            case '\'':
                result.append('\'');
                break;
            case '\\':
                result.append('\\');
                break;
            case 'u': {
                while (i + 1 < input.length() && input.charAt(i + 1) == 'u') {
                    i++;
                }

                int start = i + 1;
                int end = start + 4;
                if (end > input.length()) {
                    throw new IllegalArgumentException("Incomplete Unicode escape");
                }

                int value = 0;
                for (int j = start; j < end; j++) {
                    int digit = Character.digit(input.charAt(j), 16);
                    if (digit < 0) {
                        throw new IllegalArgumentException(
                                "Invalid Unicode escape: " + input.substring(start, end));
                    }
                    value = (value << 4) | digit;
                }

                result.append((char) value);
                i = end - 1;
                break;
            }
            default:
                if (c >= '0' && c <= '7') {
                    int value = c - '0';
                    int maxDigits = c <= '3' ? 3 : 2;
                    int digits = 1;

                    while (digits < maxDigits
                            && i + 1 < input.length()
                            && input.charAt(i + 1) >= '0'
                            && input.charAt(i + 1) <= '7') {
                        value = (value << 3) + (input.charAt(++i) - '0');
                        digits++;
                    }

                    result.append((char) value);
                } else {
                    result.append(c);
                }
        }
    }

    return result.toString();
}

