        throw new NullPointerException("byteArrayValue");
    }
    if (byteOffset < 0 || byteLength < 0 || byteOffset > byteArrayValue.length - byteLength) {
        throw new IndexOutOfBoundsException();
    }
    if (length + byteLength > data.length) {
        int newCapacity = Math.max(length + byteLength, data.length * 2);
        data = java.util.Arrays.copyOf(data, newCapacity);
    }
    System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    length += byteLength;
    return this;
}

