@Override
public Action inspect(AtmosphereResource r) {
    if (r == null || r.getRequest() == null) {
        return Action.CONTINUE;
    }

    String transport = r.getRequest().getHeader("X-Atmosphere-Transport");
    if (transport == null) {
        transport = r.getRequest().getParameter("transport");
    }

    if ("polling".equalsIgnoreCase(transport)
            || "long-polling".equalsIgnoreCase(transport)
            || "streaming".equalsIgnoreCase(transport)
            || "sse".equalsIgnoreCase(transport)) {
        return Action.SUSPEND;
    }

    return Action.CONTINUE;
}

