    }
    if (vertex < 0 || vertex >= graph.length) {
        throw new IndexOutOfBoundsException("Invalid vertex: " + vertex);
    }

    int weight = 0;
    for (int[] edges : graph) {
        if (edges == null || vertex >= edges.length) {
            throw new IllegalArgumentException("Graph must be a square adjacency matrix");
        }
        weight += edges[vertex];
    }
    return weight;
}

