public static int vertexWeight(int vertex, int[][] edges) {
    if (edges == null) {
        return 0;
    }

    long sum = 0;
    for (int[] edge : edges) {
        if (edge != null && edge.length >= 3 && edge[1] == vertex) {
            sum += edge[2];
        }
    }

    return Math.toIntExact(sum);
}

