public static int[] edgeSetToTour(int[][] edgeSet) {
    if (edgeSet == null || edgeSet.length == 0) {
        return new int[0];
    }

    java.util.Map<Integer, java.util.List<Integer>> graph = new java.util.HashMap<>();
    for (int[] edge : edgeSet) {
        if (edge == null || edge.length < 2) {
            throw new IllegalArgumentException("Each edge must contain two vertices");
        }
        graph.computeIfAbsent(edge[0], k -> new java.util.ArrayList<>()).add(edge[1]);
        graph.computeIfAbsent(edge[1], k -> new java.util.ArrayList<>()).add(edge[0]);
    }

    int start = edgeSet[0][0];
    for (java.util.Map.Entry<Integer, java.util.List<Integer>> entry : graph.entrySet()) {
        int degree = entry.getValue().size();
        if (degree > 2) {
            throw new IllegalArgumentException("Edge set does not form a path or cycle");
        }
        if (degree == 1) {
            start = entry.getKey();
            break;
        }
    }

    int[] tour = new int[edgeSet.length + 1];
    int previous = Integer.MIN_VALUE;
    int current = start;

    for (int i = 0; i < tour.length; i++) {
        tour[i] = current;
        if (i == tour.length - 1) {
            break;
        }

        java.util.List<Integer> neighbors = graph.get(current);
        if (neighbors == null || neighbors.isEmpty()) {
            throw new IllegalArgumentException("Edge set is disconnected");
        }

        int next = neighbors.get(0);
        if (next == previous && neighbors.size() > 1) {
            next = neighbors.get(1);
        } else if (next == previous) {
            throw new IllegalArgumentException("Edge set does not form a continuous path");
        }

        previous = current;
        current = next;
    }

    return tour;
}

