    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(
            graph, null, null, Collections.emptyList(), Collections.emptyList(), 0.0);
    }

    Map<V, List<E>> incidentEdges = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        incidentEdges.computeIfAbsent(source, v -> new ArrayList<>()).add(edge);
        incidentEdges.computeIfAbsent(target, v -> new ArrayList<>()).add(edge);
    }

    V start = incidentEdges.entrySet().stream()
        .filter(entry -> entry.getValue().size() % 2 != 0)
        .map(Map.Entry::getKey)
        .findFirst()
        .orElseGet(() -> incidentEdges.keySet().iterator().next());

    Set<E> unused = new HashSet<>(tour);
    Deque<V> vertexStack = new ArrayDeque<>();
    Deque<E> edgeStack = new ArrayDeque<>();
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    vertexStack.push(start);

    while (!vertexStack.isEmpty()) {
        V vertex = vertexStack.peek();
        E nextEdge = null;

        for (E edge : incidentEdges.getOrDefault(vertex, Collections.emptyList())) {
            if (unused.remove(edge)) {
                nextEdge = edge;
                break;
            }
