            V source = graph.getEdgeSource(nextEdge);
            V target = graph.getEdgeTarget(nextEdge);
            V nextVertex = vertex.equals(source) ? target : source;
            edgeStack.push(nextEdge);
            vertexStack.push(nextVertex);
