protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    Objects.requireNonNull(tour, "tour must not be null");
    Objects.requireNonNull(graph, "graph must not be null");

    if (tour.isEmpty()) {
        if (graph.vertexSet().isEmpty()) {
            return new GraphWalk<>(
                    graph,
                    Collections.emptyList(),
                    Collections.emptyList(),
                    0.0);
        }

        V vertex = graph.vertexSet().iterator().next();
        return new GraphWalk<>(
                graph,
                Collections.singletonList(vertex),
                Collections.emptyList(),
                0.0);
    }

    Map<V, List<E>> incidentEdges = new LinkedHashMap<>();
    for (E edge : tour) {
        if (edge == null || !graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains an edge not present in the graph");
        }

        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        incidentEdges.computeIfAbsent(source, ignored -> new ArrayList<>()).add(edge);
        incidentEdges.computeIfAbsent(target, ignored -> new ArrayList<>()).add(edge);
    }

    for (Map.Entry<V, List<E>> entry : incidentEdges.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException(
                    "Edge set does not form a tour: vertex " + entry.getKey()
                            + " has degree " + entry.getValue().size());
        }
    }

    E firstEdge = tour.iterator().next();
    V start = graph.getEdgeSource(firstEdge);
    V current = start;

    List<V> vertices = new ArrayList<>(tour.size() + 1);
    List<E> edges = new ArrayList<>(tour.size());
    Set<E> unused = new LinkedHashSet<>(tour);
    double weight = 0.0;

    vertices.add(start);

    while (!unused.isEmpty()) {
        E next = null;
        for (E edge : incidentEdges.getOrDefault(current, Collections.emptyList())) {
            if (unused.contains(edge)) {
                next = edge;
                break;
            }
        }

        if (next == null) {
            throw new IllegalArgumentException(
                    "Edge set is disconnected or does not form a continuous tour");
        }

        V source = graph.getEdgeSource(next);
        V target = graph.getEdgeTarget(next);
        V nextVertex;

        if (Objects.equals(current, source)) {
            nextVertex = target;
        } else if (Objects.equals(current, target)) {
            nextVertex = source;
        } else {
            throw new IllegalArgumentException("Encountered a non-incident tour edge");
        }

        unused.remove(next);
        edges.add(next);
        vertices.add(nextVertex);
        weight += graph.getEdgeWeight(next);
        current = nextVertex;
    }

    if (!Objects.equals(current, start)) {
        throw new IllegalArgumentException("Edge set does not form a closed tour");
    }

    return new GraphWalk<>(graph, start, start, vertices, edges, weight);
}

