    for (Integer vertex : minBucket) {
        if (vertex == null || vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Invalid vertex: " + vertex);
        }
    }

    for (Integer vertex : minBucket) {
        labels.set(vertex, 0);
    }
    zeroBucket.addAll(minBucket);
