public static int countOccurrencesOf(String str, String substring) {
    if (str == null || substring == null || substring.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;

    while ((index = str.indexOf(substring, index)) != -1) {
        count++;
        index += substring.length();
    }

    return count;
}

