private Class<?> findClass(final String className) throws ClassNotFoundException {
    if (className == null || className.trim().isEmpty()) {
        throw new ClassNotFoundException("Class name must not be null or empty");
    }

    final ClassLoader contextClassLoader = Thread.currentThread().getContextClassLoader();
    if (contextClassLoader != null) {
        try {
            return Class.forName(className, false, contextClassLoader);
        } catch (ClassNotFoundException ignored) {
            // Fall back to the class loader that loaded this class.
        }
    }

    final ClassLoader definingClassLoader = getClass().getClassLoader();
    if (definingClassLoader != contextClassLoader) {
        return Class.forName(className, false, definingClassLoader);
    }

    throw new ClassNotFoundException(className);
}

