    if (node == null || node.next == null || node.prev == null) {
        return false;
    }

    if (node.next == node && node.prev == node) {
        node.next = null;
        node.prev = null;
        return true;
    }

    if (node.prev.next != node || node.next.prev != node) {
        return false;
    }

    node.prev.next = node.next;
    node.next.prev = node.prev;
    node.next = null;
    node.prev = null;
    return true;
}

