private List<long[]> buildSequenceRanges(long minSequence, long maxSequence) {
    List<long[]> ranges = new ArrayList<>();

    if (minSequence > maxSequence) {
        return ranges;
    }

    for (long lowerBound = minSequence; lowerBound <= maxSequence; ) {
        long upperBound = lowerBound > maxSequence - SEQUENCE_RANGE_BATCH_SIZE + 1
                ? maxSequence
                : lowerBound + SEQUENCE_RANGE_BATCH_SIZE - 1;

        ranges.add(new long[]{lowerBound, upperBound});

        if (upperBound == maxSequence) {
            break;
        }
        lowerBound = upperBound + 1;
    }

    return ranges;
}

