private static List<long[]> buildSequenceRanges(
        long minSequence,
        long maxSequence,
        long SEQUENCE_RANGE_BATCH_SIZE) {

    if (SEQUENCE_RANGE_BATCH_SIZE <= 0) {
        throw new IllegalArgumentException("SEQUENCE_RANGE_BATCH_SIZE must be positive");
    }

    List<long[]> ranges = new ArrayList<>();
    if (minSequence > maxSequence) {
        return ranges;
    }

    long upperBound = minSequence;
    while (true) {
        ranges.add(new long[]{minSequence, upperBound});

        if (upperBound == maxSequence) {
            break;
        }

        long remaining = maxSequence - upperBound;
        upperBound = remaining <= SEQUENCE_RANGE_BATCH_SIZE
                ? maxSequence
                : upperBound + SEQUENCE_RANGE_BATCH_SIZE;
    }

    return ranges;
}

