    int separatorIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int extensionIndex = path.lastIndexOf('.');

    return extensionIndex > separatorIndex ? path.substring(0, extensionIndex) : path;
}

