public static void selectRow(JTable table, JScrollPane scrollPane, int row) {
    if (table == null || scrollPane == null || row < 0 || row >= table.getRowCount()) {
        return;
    }

    table.setRowSelectionInterval(row, row);
    Rectangle rowBounds = table.getCellRect(row, 0, true);
    table.scrollRectToVisible(rowBounds);

    JViewport viewport = scrollPane.getViewport();
    if (viewport.getView() == table) {
        Point position = viewport.getViewPosition();
        position.y = Math.max(0, Math.min(rowBounds.y,
                table.getHeight() - viewport.getExtentSize().height));
        viewport.setViewPosition(position);
    }
}

