public static void selectRow(JTable table, JScrollPane scrollPane, int row) {
    if (table == null || scrollPane == null) {
        throw new IllegalArgumentException("table and scrollPane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IndexOutOfBoundsException("Invalid row index: " + row);
    }

    Runnable selection = () -> {
        table.getSelectionModel().setSelectionInterval(row, row);

        Rectangle rowBounds = table.getCellRect(row, 0, true);
        JViewport viewport = scrollPane.getViewport();
        Rectangle viewRect = viewport.getViewRect();

        rowBounds.x = viewRect.x;
        rowBounds.width = viewRect.width;
        table.scrollRectToVisible(rowBounds);
    };

    if (SwingUtilities.isEventDispatchThread()) {
        selection.run();
    } else {
        try {
            SwingUtilities.invokeAndWait(selection);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("Interrupted while selecting the row", e);
        } catch (InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof RuntimeException) {
                throw (RuntimeException) cause;
            }
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            throw new IllegalStateException("Failed to select the row", cause);
        }
    }
}

