public static String buildContentRange(long offset, long limit, long count) {
    if (offset < 0 || limit < 0 || count < 0) {
        throw new IllegalArgumentException("offset, limit, and count must be non-negative");
    }

    if (count == 0) {
        return "bytes */0";
    }

    if (offset >= count) {
        throw new IllegalArgumentException("offset must be less than count");
    }

    long upperBound = limit == 0
            ? count - 1
            : Math.min(count - 1, offset > Long.MAX_VALUE - limit + 1
                    ? Long.MAX_VALUE
                    : offset + limit - 1);

    return "bytes " + offset + "-" + upperBound + "/" + count;
}

