        File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.isFile()) {
        throw new FileNotFoundException("File does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return Collections.emptyList();
    }

    List<ThreadSnapshot> snapshots = parseFromFile(file);
    if (snapshots == null || snapshots.isEmpty()) {
        return Collections.emptyList();
    }

    List<ProfileAnalyzeTimeRange> ranges = timeRanges.stream()
            .filter(Objects::nonNull)
            .sorted(Comparator.comparingLong(ProfileAnalyzeTimeRange::getStartTime))
            .collect(Collectors.toList());

    if (ranges.isEmpty()) {
        return Collections.emptyList();
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : snapshots) {
        if (snapshot == null) {
            continue;
