        long timestamp = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange range : ranges) {
            long start = range.getStartTime();
            long end = range.getEndTime();

            if (end < start) {
                long temporary = start;
                start = end;
                end = temporary;
            }

            if (timestamp < start) {
                break;
            }
            if (timestamp <= end) {
                result.add(snapshot);
                break;
            }
        }
    }

    return result;
}

